-- create "rte_demands" table
CREATE TABLE "rte_demands" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "namespace" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "kind" character varying NOT NULL,
  "owner_id" character varying NOT NULL,
  "key_hash" character varying NOT NULL,
  "key" jsonb NOT NULL,
  "push_enabled" boolean NOT NULL DEFAULT false,
  "pull_until" timestamptz NULL,
  "dirty_version" bigint NOT NULL DEFAULT 1,
  "completed_version" bigint NOT NULL DEFAULT 0,
  "refresh_interval" bigint NOT NULL DEFAULT 0,
  "next_refresh_at" timestamptz NULL,
  "last_calculated_at" timestamptz NULL,
  "next_attempt_at" timestamptz NOT NULL,
  "attempts" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
-- create index "rte_demand_identity" to table: "rte_demands"
CREATE UNIQUE INDEX "rte_demand_identity" ON "rte_demands" ("namespace", "kind", "key_hash") WHERE (deleted_at IS NULL);
-- create index "rte_demand_owner" to table: "rte_demands"
CREATE INDEX "rte_demand_owner" ON "rte_demands" ("namespace", "kind", "owner_id");
-- create index "rte_demand_work" to table: "rte_demands"
CREATE INDEX "rte_demand_work" ON "rte_demands" ("next_attempt_at", "id") WHERE ((deleted_at IS NULL) AND push_enabled AND ((dirty_version > completed_version) OR (next_refresh_at IS NOT NULL)));
-- create index "rtedemand_namespace" to table: "rte_demands"
CREATE INDEX "rtedemand_namespace" ON "rte_demands" ("namespace");
-- create "rte_invalidations" table
CREATE TABLE "rte_invalidations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "source" character varying NOT NULL,
  "event_id" character varying NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "rte_invalidation_retention" to table: "rte_invalidations"
CREATE INDEX "rte_invalidation_retention" ON "rte_invalidations" ("created_at", "id");
-- create index "rteinvalidation_source_event_id" to table: "rte_invalidations"
CREATE UNIQUE INDEX "rteinvalidation_source_event_id" ON "rte_invalidations" ("source", "event_id");
